"use client";

import React, { useState, useEffect } from "react";
import UploadReplay from "./UploadReplay";
import { useRouter } from "next/navigation";

export default function UploadPage() {
  const router = useRouter();
  const [password, setPassword] = useState("");
  const [loggedIn, setLoggedIn] = useState(false);

  useEffect(() => {
    const stored = localStorage.getItem("staffLoggedIn");
    if (stored === "true") setLoggedIn(true);
  }, []);

  const handleLogin = async () => {
    if (!password) return alert("Enter password");

    const res = await fetch("/api/login", {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ password }),
    });

    const data = await res.json();
    if (data.success) {
      localStorage.setItem("staffLoggedIn", "true");
      setLoggedIn(true);
      setPassword("");
    } else {
      alert("Wrong password");
    }
  };

  const handleLogout = () => {
    localStorage.removeItem("staffLoggedIn");
    setLoggedIn(false);
  };

  if (!loggedIn)
    return (
      <div className="min-h-screen flex flex-col items-center justify-center p-4">
        <div className="absolute top-4 left-4">
          <a href="/" className="btn-back">← Back</a>
        </div>
        <div className="card p-8 w-full max-w-md text-center">
          <h2 className="text-2xl font-bold text-white mb-6">NCL Mod Login</h2>

          <input
            type="password"
            placeholder="Enter staff password"
            value={password}
            onChange={(e) => setPassword(e.target.value)}
            className="field mb-4"
          />

          <button onClick={handleLogin} className="btn btn-primary w-full py-3">
            Log in
          </button>
        </div>
      </div>
    );

  return (
    <div className="min-h-screen flex flex-col items-center justify-center p-4">
      <div className="absolute top-4 right-4">
        <button onClick={handleLogout} className="btn btn-secondary">
          Sign Out
        </button>
      </div>
      <div className="w-full max-w-xl">
        <UploadReplay />
      </div>
    </div>
  );
}